INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'offshore-pipe-piles','Offshore Engineering Pipe Piles','海洋工程钢管桩','Energy infrastructure','能源基础设施','Conquer the challenges of marine construction with our heavy-duty Offshore Engineering Pipe Piles. Specifically designed for the harsh saltwater environment, our large-diameter steel pipe piles provide the fundamental support for the world''s most demanding offshore structures. From oil platforms and wind turbine foundations to deep-water ports and artificial islands, our piling solutions are engineered to withstand dynamic wave loads, seismic activity, and long-term corrosion. Manufactured to strict international standards (API, ASTM, EN), these piles deliver the structural integrity and fatigue resistance required for 25+ year service life in open water.','面向海上平台、风电基础、深水港及人工岛的大直径钢管桩，结合波浪、海流、船舶冲击及腐蚀等海洋工况设计制造。','Conquer the challenges of marine construction with our heavy-duty Offshore Engineering Pipe Piles. Specifically designed for the harsh saltwater environment, our large-diameter steel pipe piles provide the fundamental support for the world''s most demanding offshore structures. From oil platforms and wind turbine foundations to deep-water ports and artificial islands, our piling solutions are engineered to withstand dynamic wave loads, seismic activity, and long-term corrosion. Manufactured to strict international standards (API, ASTM, EN), these piles deliver the structural integrity and fatigue resistance required for 25+ year service life in open water.','面向海上平台、风电基础、深水港及人工岛的大直径钢管桩，结合波浪、海流、船舶冲击及腐蚀等海洋工况设计制造。','Offshore Engineering Steel Pipe Piles | Marine Foundation Solutions
Our Offshore Engineering Pipe Piles are the backbone of marine infrastructure. Fabricated from high-grade steel (API 5L, ASTM A572, EH36/Z35), these piles are engineered to penetrate deep seabeds and provide secure anchoring for fixed and floating structures in water depths up to 50m+.
Exceptional Load Capacity: Designed to handle massive axial and lateral loads from wind, waves, currents, and vessel impacts.
Superior Toughness: Steel grades with Charpy V-Notch impact testing guarantee performance in low-temperature marine environments.
Corrosion Protection: Available with anti-corrosion coatings (FBE/3LPE), concrete encasement, or corrosion allowance designs to extend service life.
Precision Fabrication: Automated welding (LSAW/SSAW) ensures straightness, roundness, and consistent wall thickness for reliable driving.
Heavy-Duty Connections: Engineered transition pieces and pile shoes for easy driving and integration with jacket structures or monopiles.
End Options: Available with beveled ends for welding, internal/external stiffeners, or rock shoes for challenging seabed conditions.','承受轴向及横向载荷
结合海洋低温工况选择钢材韧性
可选防腐涂层、混凝土包覆或腐蚀余量设计
焊接制造控制直线度、圆度与壁厚
可配置过渡段、桩靴及加强结构','','','/assets/tzme-products/offshore-pipe-piles.webp','published',0,0,'products','Offshore Engineering Pipe Piles','Energy infrastructure','Conquer the challenges of marine construction with our heavy-duty Offshore Engineering Pipe Piles. Specifically designed for the harsh saltwater environment, our large-diameter steel pipe piles provide the fundamental support for the world''s most demanding offshore structures. From oil platforms and wind turbine foundations to deep-water ports and artificial islands, our piling solutions are engineered to withstand dynamic wave loads, seismic activity, and long-term corrosion. Manufactured to strict international standards (API, ASTM, EN), these piles deliver the structural integrity and fatigue resistance required for 25+ year service life in open water.','Conquer the challenges of marine construction with our heavy-duty Offshore Engineering Pipe Piles. Specifically designed for the harsh saltwater environment, our large-diameter steel pipe piles provide the fundamental support for the world''s most demanding offshore structures. From oil platforms and wind turbine foundations to deep-water ports and artificial islands, our piling solutions are engineered to withstand dynamic wave loads, seismic activity, and long-term corrosion. Manufactured to strict international standards (API, ASTM, EN), these piles deliver the structural integrity and fatigue resistance required for 25+ year service life in open water.','energy','energy,ports',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='offshore-pipe-piles');
